#!/bin/sh
# mkrustcorpus.sh HBNF TEMPLATES HBNF_GRAMMARS PDP64_ROOT OUTDIR -- the Rust corpus: Rust parsers generated by hbnf from six grammars.
# HBNF is the hbnf binary, TEMPLATES its template directory, HBNF_GRAMMARS the grammars directory of the hbnf repository (bech32, obconf, obconf_roundtrip),
# PDP64_ROOT this repository (the assembler grammar spec/pdp64-asm.hbnf after tools/build-as64.sh has made build/x, and the encoding grammar spec/pdp64/pdp64.hbnf).
# The code is machine-generated (parsers: byte-buffer indexing, slices, counters), not hand-written Rust, and it is what rustc compiles here as a library
# (`rustc --crate-type=lib -C opt-level=3`); tools/arch-compare/rustcheck.py measures its run-time checks.  See corpus-rust.txt.
set -eu
H=$1; T=$2; G=$3; R=$4; O=$5; mkdir -p "$O"
for n in bech32 obconf obconf_roundtrip; do (cd "$G" && "$H" $n.hbnf --backend=rust --templates="$T" --quiet-forks) > "$O/$n.rs"; done
(cd "$R/build/x" && "$H" pdp64-asm.hbnf --backend=rust --templates="$T" --quiet-forks) > "$O/pdp64-asm.rs"
(cd "$R/build/x" && "$H" pdp64-asm.hbnf --backend=rust --templates="$T" --ast --spans --no-compact --no-overlay --quiet-forks) > "$O/pdp64-asm-ast.rs"
(cd "$R/spec/pdp64" && "$H" pdp64.hbnf --backend=rust --templates="$T" --quiet-forks) > "$O/spec-pdp64.rs"
wc -l "$O"/*.rs
